        <S01_SecHdr num="08" label="Venture Portfolio" badge="18 ventures" hint="Tier 1: $8–25M+ · Kejetia Platform anchor · 7 direct market infrastructure ventures" open={secOpen} onToggle={()=>setSecOpen(o=>!o)} dark={false}/>
