const S01_ExpandCtx=React.createContext({forceOpen:null});

function S01_InfrastructureBrief(){
  const coverRef=useRef(null);
  const[forceOpen,setForceOpen]=useState(null); // null=local, true=all open, false=all closed
  const[barAllOpen,setBarAllOpen]=useState(false);
  const toggleAll=()=>{
    const next=!barAllOpen;
    setBarAllOpen(next);
    setForceOpen(next);
    // Reset after a tick so local state takes over on next individual toggle
    setTimeout(()=>setForceOpen(null),50);
  };
  return(
    <S01_ExpandCtx.Provider value={{forceOpen}}>
    <div style={{fontFamily:F.body,background:C.paper,paddingBottom:'60px'}}>
      <S01_Gf/>
      <S01_ReadingProgressBar coverRef={coverRef}/>
      <S01_SectionFooterNav/>
      <S01_Cover logoRef={coverRef}/>
      <S01_MobExpandBar allOpen={barAllOpen} onToggle={toggleAll}/>
      <S01_Executive/>
      <S01_SubSectors/>
      <S01_StructuralProblem/>
      <S01_WashCrisis/>
      <S01_KejetiaFlagship/>
      <S01_RegionalComparison/>
      <S01_PolicyWindow/>
      <S01_SystemIntegration/>
      <S01_VenturePipeline/>
      <S01_DeploymentTimeline/>
      <S01_CrossSectorSynergy/>
      <S01_CoInvestmentLandscape/>
      <S01_RiskThesis/>
      <S01_Upsell/>
      <S01_Footer/>
    </div>
    </S01_ExpandCtx.Provider>
  );
}


