const S03_ExpandCtx=React.createContext({forceOpen:null});

function S03_HealthBrief(){
  const coverRef=useRef(null);
  const[forceOpen,setForceOpen]=useState(null); // null=local, true=all open, false=all closed
  const[barAllOpen,setBarAllOpen]=useState(false);
  const toggleAll=()=>{
    const next=!barAllOpen;
    setBarAllOpen(next);
    setForceOpen(next);
    setTimeout(()=>setForceOpen(null),50);
  };
  return(
    <S03_ExpandCtx.Provider value={{forceOpen}}>
    {/* paddingBottom:60px keeps last section above fixed S03_SectionFooterNav */}
    <div style={{fontFamily:F.body,background:C.paper,paddingBottom:'60px'}}>
      <S03_Gf/>
      <S03_ReadingProgressBar coverRef={coverRef}/>
      <S03_SectionFooterNav/>
      <S03_Cover logoRef={coverRef}/>
      <S03_MobExpandBar allOpen={barAllOpen} onToggle={toggleAll}/>
      <S03_Executive/>
      <S03_SubSectors/>
      <S03_StructuralProblem/>
      <S03_BrainDrain/>
      <S03_DiasporaAdvantage/>
      <S03_CompetitiveLandscape/>
      <S03_HealthFinancing/>
      <S03_CrossSectorIntegration/>
      <S03_VenturePipeline/>
      <S03_DeploymentTimeline/>
      <S03_CrossSectorSynergy/>
      <S03_CoInvestmentLandscape/>
      <S03_RiskThesis/>
      <S03_Upsell/>
      <S03_Footer/>
    </div>
    </S03_ExpandCtx.Provider>
  );
}


