const S04_ExpandCtx=React.createContext({forceOpen:null});

function S04_TechnologyBrief(){
  const coverRef=useRef(null);
  const[forceOpen,setForceOpen]=useState(null); // null=local, true=all open, false=all closed
  const[barAllOpen,setBarAllOpen]=useState(false);
  const toggleAll=()=>{
    const next=!barAllOpen;
    setBarAllOpen(next);
    setForceOpen(next);
    // Reset after a tick so local state takes over on next individual toggle
    setTimeout(()=>setForceOpen(null),50);
  };
  return(
    <S04_ExpandCtx.Provider value={{forceOpen}}>
    <div style={{fontFamily:F.body,background:C.paper,paddingBottom:'60px'}}>
      <S04_Gf/>
      <S04_ReadingProgressBar coverRef={coverRef}/>
      <S04_SectionFooterNav/>
      <S04_Cover logoRef={coverRef}/>
      <S04_MobExpandBar allOpen={barAllOpen} onToggle={toggleAll}/>
      <S04_Executive/>
      <S04_SubSectors/>
      <S04_StructuralProblem/>
      <S04_CropAnalysis/>
      <S04_RegionalStrategy/>
      <S04_CompetitiveLandscape/>
      <S04_PolicyWindow/>
      <S04_FarmerIncome/>
      <S04_VenturePipeline/>
      <S04_DeploymentTimeline/>
      <S04_CrossSectorSynergy/>
      <S04_CoInvestmentLandscape/>
      <S04_RiskThesis/>
      <S04_Upsell/>
      <S04_Footer/>
    </div>
    </S04_ExpandCtx.Provider>
  );
}


