const S05_ExpandCtx=React.createContext({forceOpen:null});

function S05_EducationBrief(){
  const coverRef=useRef(null);
  const[forceOpen,setForceOpen]=useState(null); // null=local, true=all open, false=all closed
  const[barAllOpen,setBarAllOpen]=useState(false);
  const toggleAll=()=>{
    const next=!barAllOpen;
    setBarAllOpen(next);
    setForceOpen(next);
    // Reset after a tick so local state takes over on next individual toggle
    setTimeout(()=>setForceOpen(null),50);
  };
  return(
    <S05_ExpandCtx.Provider value={{forceOpen}}>
    <div style={{fontFamily:F.body,background:C.paper,paddingBottom:'60px'}}>
      <S05_Gf/>
      <S05_ReadingProgressBar coverRef={coverRef}/>
      <S05_SectionFooterNav/>
      <S05_Cover logoRef={coverRef}/>
      <S05_MobExpandBar allOpen={barAllOpen} onToggle={toggleAll}/>
      <S05_Executive/>
      <S05_SubSectors/>
      <S05_StructuralProblem/>
      <S05_CropAnalysis/>
      <S05_RegionalStrategy/>
      <S05_CompetitiveLandscape/>
      <S05_PolicyWindow/>
      <S05_FarmerIncome/>
      <S05_VenturePipeline/>
      <S05_DeploymentTimeline/>
      <S05_CrossSectorSynergy/>
      <S05_CoInvestmentLandscape/>
      <S05_RiskThesis/>
      <S05_Upsell/>
      <S05_Footer/>
    </div>
    </S05_ExpandCtx.Provider>
  );
}


