/* ═══ MOBILE DETECT HOOK ════════════════════════════════════════════════ */
const S07_useMobile=()=>{
  const[mob,setMob]=useState(typeof window!=='undefined'&&window.innerWidth<=600);
  useEffect(()=>{
    const fn=()=>setMob(window.innerWidth<=600);
    window.addEventListener('resize',fn,{passive:true});
    return()=>window.removeEventListener('resize',fn);
  },[]);
  return mob;
};

