const S07_ExpandCtx=React.createContext({forceOpen:null});

function S07_SportsBrief(){
  const coverRef=useRef(null);
  const[forceOpen,setForceOpen]=useState(null); // null=local, true=all open, false=all closed
  const[barAllOpen,setBarAllOpen]=useState(false);
  const toggleAll=()=>{
    const next=!barAllOpen;
    setBarAllOpen(next);
    setForceOpen(next);
    // Reset after a tick so local state takes over on next individual toggle
    setTimeout(()=>setForceOpen(null),50);
  };
  return(
    <S07_ExpandCtx.Provider value={{forceOpen}}>
    <div style={{fontFamily:F.body,background:C.paper,paddingBottom:'60px'}}>
      <S07_Gf/>
      <S07_ReadingProgressBar coverRef={coverRef}/>
      <S07_SectionFooterNav/>
      <S07_Cover logoRef={coverRef}/>
      <S07_MobExpandBar allOpen={barAllOpen} onToggle={toggleAll}/>
      <S07_Executive/>
      <S07_SubSectors/>
      <S07_StructuralProblem/>
      <S07_CropAnalysis/>
      <S07_RegionalStrategy/>
      <S07_CompetitiveLandscape/>
      <S07_PolicyWindow/>
      <S07_FarmerIncome/>
      <S07_VenturePipeline/>
      <S07_DeploymentTimeline/>
      <S07_CrossSectorSynergy/>
      <S07_CoInvestmentLandscape/>
      <S07_RiskThesis/>
      <S07_Upsell/>
      <S07_Footer/>
    </div>
    </S07_ExpandCtx.Provider>
  );
}


