const S08_ExpandCtx=React.createContext({forceOpen:null});

function S08_HousingBrief(){
  const coverRef=useRef(null);
  const[forceOpen,setForceOpen]=useState(null); // null=local, true=all open, false=all closed
  const[barAllOpen,setBarAllOpen]=useState(false);
  const toggleAll=()=>{
    const next=!barAllOpen;
    setBarAllOpen(next);
    setForceOpen(next);
    // Reset after a tick so local state takes over on next individual toggle
    setTimeout(()=>setForceOpen(null),50);
  };
  return(
    <S08_ExpandCtx.Provider value={{forceOpen}}>
    <div style={{fontFamily:F.body,background:C.paper,paddingBottom:'60px'}}>
      <S08_Gf/>
      <S08_ReadingProgressBar coverRef={coverRef}/>
      <S08_SectionFooterNav/>
      <S08_Cover logoRef={coverRef}/>
      <S08_MobExpandBar allOpen={barAllOpen} onToggle={toggleAll}/>
      <S08_Executive/>
      <S08_SubSectors/>
      <S08_SupplyGap/>
      <S08_FinanceBarriers/>
      <S08_LandTenure/>
      <S08_ConstructionQuality/>
      <S08_MarketOpportunity/>
      <S08_PortfolioOverview/>
      <S08_VenturePipeline/>
      <S08_DeploymentTimeline/>
      <S08_CrossSectorSynergy/>
      <S08_CoInvestmentLandscape/>
      <S08_RiskThesis/>
      <S08_Upsell/>
      <S08_Footer/>
    </div>
    </S08_ExpandCtx.Provider>
  );
}


