const S10_ExpandCtx=React.createContext({forceOpen:null});

function S10_EnergyBrief(){
  const coverRef=useRef(null);
  const[forceOpen,setForceOpen]=useState(null);
  const[barAllOpen,setBarAllOpen]=useState(false);
  const toggleAll=()=>{
    const next=!barAllOpen;
    setBarAllOpen(next);
    setForceOpen(next);
    setTimeout(()=>setForceOpen(null),50);
  };
  return(
    <S10_ExpandCtx.Provider value={{forceOpen}}>
    <div style={{fontFamily:F.body,background:C.paper,paddingBottom:'60px'}}>
      <S10_Gf/>
      <S10_ReadingProgressBar coverRef={coverRef}/>
      <S10_SectionFooterNav/>
      <S10_Cover logoRef={coverRef}/>
      <S10_MobExpandBar allOpen={barAllOpen} onToggle={toggleAll}/>
      <S10_Executive/>
      <S10_SubSectors/>
      <S10_StructuralProblem/>
      <S10_OutageEconomics/>
      <S10_RegionalStrategy/>
      <S10_CompetitiveLandscape/>
      <S10_PolicyWindow/>
      <S10_EnergyAccess/>
      <S10_VenturePipeline/>
      <S10_DeploymentTimeline/>
      <S10_CrossSectorSynergy/>
      <S10_CoInvestmentLandscape/>
      <S10_RiskThesis/>
      <S10_Upsell/>
      <S10_Footer/>
    </div>
    </S10_ExpandCtx.Provider>
  );
}


