const S11_ExpandCtx=React.createContext({forceOpen:null});

function S11_ManufacturingBrief(){
  const coverRef=useRef(null);
  const[forceOpen,setForceOpen]=useState(null); // null=local, true=all open, false=all closed
  const[barAllOpen,setBarAllOpen]=useState(false);
  const toggleAll=()=>{
    const next=!barAllOpen;
    setBarAllOpen(next);
    setForceOpen(next);
    // Reset after a tick so local state takes over on next individual toggle
    setTimeout(()=>setForceOpen(null),50);
  };
  return(
    <S11_ExpandCtx.Provider value={{forceOpen}}>
    <div style={{fontFamily:F.body,background:C.paper,paddingBottom:'60px'}}>
      <S11_Gf/>
      <S11_ReadingProgressBar coverRef={coverRef}/>
      <S11_SectionFooterNav/>
      <S11_Cover logoRef={coverRef}/>
      <S11_MobExpandBar allOpen={barAllOpen} onToggle={toggleAll}/>
      <S11_Executive/>
      <S11_SubSectors/>
      <S11_StructuralProblem/>
      <S11_CropAnalysis/>
      <S11_RegionalStrategy/>
      <S11_CompetitiveLandscape/>
      <S11_PolicyWindow/>
      <S11_FarmerIncome/>
      <S11_VenturePipeline/>
      <S11_DeploymentTimeline/>
      <S11_CrossSectorSynergy/>
      <S11_CoInvestmentLandscape/>
      <S11_RiskThesis/>
      <S11_Upsell/>
      <S11_Footer/>
    </div>
    </S11_ExpandCtx.Provider>
  );
}


