/* ═══ ROOT ════════════════════════════════════════════════════════════════ */
const S12_ExpandCtx=React.createContext({forceOpen:null});

function S12_TransportationBrief(){
  const coverRef=useRef(null);
  const[forceOpen,setForceOpen]=useState(null); // null=local, true=all open, false=all closed
  const[barAllOpen,setBarAllOpen]=useState(false);
  const toggleAll=()=>{
    const next=!barAllOpen;
    setBarAllOpen(next);
    setForceOpen(next);
    // Reset after a tick so local state takes over on next individual toggle
    setTimeout(()=>setForceOpen(null),50);
  };
  return(
    <S12_ExpandCtx.Provider value={{forceOpen}}>
    <div style={{fontFamily:F.body,background:C.paper,paddingBottom:'60px'}}>
      <S12_Gf/>
      <S12_ReadingProgressBar coverRef={coverRef}/>
      <S12_SectionFooterNav/>
      <S12_Cover logoRef={coverRef}/>
      <S12_MobExpandBar allOpen={barAllOpen} onToggle={toggleAll}/>
      <S12_Executive/>
      <S12_SubSectors/>
      <S12_StructuralProblem/>
      <S12_ColdChainAnalysis/>
      <S12_RegionalStrategy/>
      <S12_CompetitiveLandscape/>
      <S12_PolicyWindow/>
      <S12_LogisticsPerformance/>
      <S12_VenturePipeline/>
      <S12_DeploymentTimeline/>
      <S12_CrossSectorSynergy/>
      <S12_CoInvestmentLandscape/>
      <S12_RiskThesis/>
      <S12_Upsell/>
      <S12_Footer/>
    </div>
    </S12_ExpandCtx.Provider>
  );
}


