export default function SectorBriefsFull() {
  const [active, setActive] = useState(1);
  const renderSector = () => {
    if(active===1) return <S01_InfrastructureBrief/>;
    if(active===2) return <S02_BRIDGE_Sector02_FinancialInclusion/>;
    if(active===3) return <S03_HealthBrief/>;
    if(active===4) return <S04_TechnologyBrief/>;
    if(active===5) return <S05_EducationBrief/>;
    if(active===6) return <S06_AgricultureBrief/>;
    if(active===7) return <S07_SportsBrief/>;
    if(active===8) return <S08_HousingBrief/>;
    if(active===9) return <S09_TourismBrief/>;
    if(active===10) return <S10_EnergyBrief/>;
    if(active===11) return <S11_ManufacturingBrief/>;
    if(active===12) return <S12_TransportationBrief/>;
    return null;
  };
  return (
    <div>
      <SectorNavigator active={active} setActive={setActive}/>
      {renderSector()}
    </div>
  );
}
